-- deploy28l: point Home V2 category tiles at the neutral images under a NEW path (tiles/v28l/), so year-long immutable browser/CDN caches of the old blue files can't be served. Idempotent; backs up _elementor_data once to _onyx_elementor_data_bak28l.
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_520_ci;
INSERT INTO wp_postmeta (post_id,meta_key,meta_value) SELECT m.post_id,'_onyx_elementor_data_bak28l',m.meta_value FROM wp_postmeta m WHERE m.post_id=(SELECT ID FROM (SELECT ID FROM wp_posts WHERE post_type='page' AND post_name='home-v2' LIMIT 1) x) AND m.meta_key='_elementor_data' AND NOT EXISTS (SELECT 1 FROM wp_postmeta b WHERE b.post_id=m.post_id AND b.meta_key='_onyx_elementor_data_bak28l');
UPDATE wp_postmeta SET meta_value=REPLACE(meta_value,'onyx-home-v2\\/tiles\\/onyx-tile-','onyx-home-v2\\/tiles\\/v28l\\/onyx-tile-') WHERE post_id=(SELECT ID FROM (SELECT ID FROM wp_posts WHERE post_type='page' AND post_name='home-v2' LIMIT 1) x) AND meta_key='_elementor_data' AND LOCATE('onyx-home-v2\\/tiles\\/onyx-tile-',meta_value)>0;
UPDATE wp_postmeta SET meta_value=REPLACE(meta_value,'onyx-home-v2/tiles/onyx-tile-','onyx-home-v2/tiles/v28l/onyx-tile-') WHERE post_id=(SELECT ID FROM (SELECT ID FROM wp_posts WHERE post_type='page' AND post_name='home-v2' LIMIT 1) x) AND meta_key='_elementor_data' AND LOCATE('onyx-home-v2/tiles/onyx-tile-',meta_value)>0;
DELETE FROM wp_postmeta WHERE post_id=(SELECT ID FROM (SELECT ID FROM wp_posts WHERE post_type='page' AND post_name='home-v2' LIMIT 1) x) AND meta_key IN ('_elementor_element_cache','_elementor_css');
